fn solve(x: i32) -> i32 {
    // Convert x to a string to easily extract the digit and its length
    let x_str = x.to_string();
    let d = x_str.chars().next().unwrap(); // Get the first character (the digit)
    let k = x_str.len() as i32; // Get the length (the number of repetitions)

    let digit = d.to_digit(10).unwrap(); // Convert char to digit (1 to 9)
    
    let mut total_presses = 0;

    // Calculate total presses for digits 1 to (digit - 1)
    for i in 1..digit {
        total_presses += (1 + 2 + 3 + 4); // 1 press for d, 2 for dd, 3 for ddd, 4 for dddd
    }

    // Calculate total presses for the current digit up to k
    total_presses += (1 + 2 + 3 + k); // Add presses for the current digit up to k

    total_presses
}